2	
3	import com.loja.checkout.domain.*;
4	import com.loja.checkout.domain.clube.Bronze;
5	import com.loja.checkout.domain.clube.NivelClube;
6	import com.loja.checkout.domain.clube.Ouro;
7	import com.loja.checkout.domain.clube.Prata;
8	import com.loja.checkout.domain.cupom.*;
9	import com.loja.checkout.domain.entrega.Economica;
10	import com.loja.checkout.domain.entrega.Expressa;
11	import com.loja.checkout.domain.entrega.ModalidadeEntrega;
12	import com.loja.checkout.domain.entrega.Motoboy;
13	import com.loja.checkout.domain.entrega.RetiradaLoja;
14	import com.loja.checkout.domain.pagamento.Boleto;
15	import com.loja.checkout.domain.pagamento.Cartao;
16	import com.loja.checkout.domain.pagamento.FormaPagamento;
17	import com.loja.checkout.domain.pagamento.Pix;
18	import com.loja.checkout.util.Dinheiro;
19	import com.loja.checkout.validacao.ValidadorPedido;
20	import org.springframework.stereotype.Service;
21	
22	import java.math.BigDecimal;
23	import java.util.Map;
24	import java.util.Optional;
25	
26	@Service
27	public class CalculadoraResumo {
28	
29	    private final ValidadorPedido validador = new ValidadorPedido();
30	
31	    private final Map<String, ModalidadeEntrega> modalidades = Map.of(
32	        "ECONOMICA", new Economica(),
33	        "EXPRESSA", new Expressa(),
34	        "RETIRADA_LOJA", new RetiradaLoja(),
35	        "MOTOBOY", new Motoboy()
36	    );
37	
38	    private final Map<String, NivelClube> niveis = Map.of(
39	        "BRONZE", new Bronze(),
40	        "PRATA", new Prata(),
41	        "OURO", new Ouro()
42	    );
43	
44	    private final Map<String, Cupom> cupons = Map.of(
45	        "BEMVINDO10", new BemVindo10(),
46	        "MENOS50", new Menos50(),
47	        "FRETEGRATIS", new FreteGratis(),
48	        "LEVE3PAGUE2", new Leve3Pague2()
49	    );
50	
51	    private final Map<String, FormaPagamento> formasPagamento = Map.of(
52	        "PIX", new Pix(),
53	        "BOLETO", new Boleto(),
54	        "CARTAO", new Cartao()
55	    );
56	
57	    public Object calcular(PedidoRequest request) {
58	        BigDecimal subtotalProdutos = calcularSubtotalProdutos(request);
59	        double pesoTotal = calcularPesoTotal(request);
60	
61	        ModalidadeEntrega modalidade = modalidades.get(request.modalidadeEntrega());
62	        NivelClube nivel = niveis.get(request.nivelClube());
63	        Regiao regiao = parseRegiao(request.regiao());
64	        FormaPagamento formaPagamento = formasPagamento.get(request.formaPagamento());
65	
66	        BigDecimal frete = calcularFrete(modalidade, nivel, pesoTotal);
67	
68	        Cupom cupom = null;
69	        if (request.cupom() != null && !request.cupom().isBlank()) {
70	            cupom = cupons.get(request.cupom());
71	        }
72	
73	        BigDecimal seguro = calcularSeguro(subtotalProdutos, regiao);
74	        BigDecimal totalPedido = subtotalProdutos.subtract(BigDecimal.ZERO).add(frete).add(seguro);
75	
76	        Optional<CodigoErro> erro = validador.validar(
77	            request, modalidade, nivel, regiao, cupom, formaPagamento,
78	            pesoTotal, subtotalProdutos, totalPedido
79	        );
80	
81	        if (erro.isPresent()) {
82	            return new ErroResponse(erro.get().name());
83	        }
84	
85	        BigDecimal descontoCupom = aplicarCupom(cupom, subtotalProdutos, request.itens(), frete);
86	
87	        if (cupom != null) {
88	            ContextoCupom contexto = new ContextoCupom(subtotalProdutos, request.itens(), frete);
89	            if (!cupom.aplicavel(contexto)) {
90	                return new ErroResponse(CodigoErro.CUPOM_NAO_APLICAVEL.name());
91	            }
92	        }
93	
94	        totalPedido = subtotalProdutos.subtract(descontoCupom).add(frete).add(seguro);
95	
96	        int parcelas = request.parcelas() != null ? request.parcelas() : 1;
97	        BigDecimal ajustePagamento = formaPagamento.calcularAjuste(totalPedido, parcelas);
98	        BigDecimal totalFinal = Dinheiro.arredondar(totalPedido.add(ajustePagamento));
99	
100	        BigDecimal valorParcela = calcularValorParcela(totalFinal, parcelas, formaPagamento, totalPedido);
101	
102	        BigDecimal credito = nivel.calcularCredito(subtotalProdutos);
103	        boolean brinde = nivel.temBrinde(subtotalProdutos);
104	
105	        int prazo = modalidade.obterPrazo();
106	
107	        return new ResumoResponse(
108	            subtotalProdutos,
109	            descontoCupom,
110	            frete,
111	            prazo,
112	            seguro,
113	            ajustePagamento,
114	            totalFinal,
115	            parcelas,
116	            valorParcela,
117	            credito,
118	            brinde
119	        );
120	    }
121	
122	    private BigDecimal calcularSubtotalProdutos(PedidoRequest request) {
123	        BigDecimal subtotal = BigDecimal.ZERO;
124	        for (var item : request.itens()) {
125	            BigDecimal precoItem = BigDecimal.valueOf(item.precoUnitario())
126	                .multiply(BigDecimal.valueOf(item.quantidade()));
127	            subtotal = subtotal.add(precoItem);
128	        }
129	        return Dinheiro.arredondar(subtotal);
130	    }
131	
132	    private double calcularPesoTotal(PedidoRequest request) {
133	        double peso = 0.0;
134	        for (var item : request.itens()) {
135	            peso += item.pesoKg() * item.quantidade();
136	        }
137	        return peso;
138	    }
139	
140	    private BigDecimal calcularFrete(ModalidadeEntrega modalidade, NivelClube nivel, double pesoTotal) {
141	        if (modalidade == null) {
142	            return Dinheiro.de(0.00);
143	        }
144	
145	        if (nivel != null && nivel.temFreteGratis()) {
146	            return Dinheiro.de(0.00);
147	        }
148	
149	        return modalidade.calcularFrete(pesoTotal);
150	    }
151	
152	    private BigDecimal calcularSeguro(BigDecimal subtotalProdutos, Regiao regiao) {
153	        if (regiao == null) {
154	            return Dinheiro.de(0.00);
155	        }
156	        return Dinheiro.percentual(subtotalProdutos, regiao.getPorcentagemSeguro());
157	    }
158	
159	    private BigDecimal aplicarCupom(Cupom cupom, BigDecimal subtotalProdutos,
160	                                    java.util.List<PedidoRequest.ItemCarrinho> itens,
161	                                    BigDecimal frete) {
162	        if (cupom == null) {
163	            return Dinheiro.de(0.00);
164	        }
165	
166	        ContextoCupom contexto = new ContextoCupom(subtotalProdutos, itens, frete);
167	        return cupom.calcularDesconto(contexto);
168	    }
169	
170	    private Regiao parseRegiao(String regiao) {
171	        if (regiao == null) return null;
172	        try {
173	            return Regiao.valueOf(regiao);
174	        } catch (IllegalArgumentException e) {
175	            return null;
176	        }
177	    }
178	
179	    private BigDecimal calcularValorParcela(BigDecimal totalFinal, int parcelas,
180	                                           FormaPagamento formaPagamento, BigDecimal totalPedido) {
181	        if (parcelas <= 1) {
182	            return totalFinal;
183	        }
184	
185	        if (formaPagamento instanceof Cartao && parcelas > 3) {
186	            double taxa = 0.0199;
187	            double fatorPrice = taxa / (1 - Math.pow(1 + taxa, -parcelas));
188	            return Dinheiro.arredondar(totalPedido.multiply(BigDecimal.valueOf(fatorPrice)));
189	        }
190	
191	        return Dinheiro.arredondar(totalFinal.divide(BigDecimal.valueOf(parcelas), 2, java.math.RoundingMode.HALF_EVEN));
192	    }
193	}
