1	package com.loja.checkout.validacao;
2	
3	import com.loja.checkout.domain.*;
4	import com.loja.checkout.domain.clube.NivelClube;
5	import com.loja.checkout.domain.cupom.Cupom;
6	import com.loja.checkout.domain.entrega.ModalidadeEntrega;
7	import com.loja.checkout.domain.pagamento.FormaPagamento;
8	
9	import java.math.BigDecimal;
10	import java.util.Optional;
11	
12	public class ValidadorPedido {
13	
14	    public Optional<CodigoErro> validar(
15	        PedidoRequest request,
16	        ModalidadeEntrega modalidade,
17	        NivelClube nivel,
18	        Regiao regiao,
19	        Cupom cupom,
20	        FormaPagamento formaPagamento,
21	        double pesoTotal,
22	        BigDecimal subtotalProdutos,
23	        BigDecimal totalPedido
24	    ) {
25	        if (!validarCarrinho(request)) {
26	            return Optional.of(CodigoErro.PEDIDO_INVALIDO);
27	        }
28	
29	        if (nivel == null) {
30	            return Optional.of(CodigoErro.NIVEL_CLUBE_INVALIDO);
31	        }
32	
33	        if (regiao == null) {
34	            return Optional.of(CodigoErro.REGIAO_INVALIDA);
35	        }
36	
37	        if (modalidade == null) {
38	            return Optional.of(CodigoErro.MODALIDADE_INVALIDA);
39	        }
40	
41	        if (!modalidade.aceitaPedido(pesoTotal)) {
42	            return Optional.of(CodigoErro.MODALIDADE_INDISPONIVEL);
43	        }
44	
45	        if (request.cupom() != null && !request.cupom().isBlank() && cupom == null) {
46	            return Optional.of(CodigoErro.CUPOM_INVALIDO);
47	        }
48	
49	        if (formaPagamento == null) {
50	            return Optional.of(CodigoErro.FORMA_PAGAMENTO_INVALIDA);
51	        }
52	
53	        int parcelas = request.parcelas() != null ? request.parcelas() : 1;
54	        if (!formaPagamento.validarParcelas(parcelas)) {
55	            return Optional.of(CodigoErro.PARCELAMENTO_INVALIDO);
56	        }
57	
58	        if (!formaPagamento.aceitaTotal(totalPedido)) {
59	            return Optional.of(CodigoErro.FORMA_PAGAMENTO_INDISPONIVEL);
60	        }
61	
62	        return Optional.empty();
63	    }
64	
65	    private boolean validarCarrinho(PedidoRequest request) {
66	        if (request.itens() == null || request.itens().isEmpty()) {
67	            return false;
68	        }
69	
70	        for (var item : request.itens()) {
71	            if (item.precoUnitario() == null || item.precoUnitario() <= 0) return false;
72	            if (item.quantidade() == null || item.quantidade() <= 0) return false;
73	            if (item.pesoKg() == null || item.pesoKg() <= 0) return false;
74	        }
75	
76	        return true;
77	    }
78	}
