11	        if (parcelas <= 3) {
12	            return Dinheiro.de(0.00);
13	        }
14	
15	        double taxa = 0.0199;
16	        double fatorPrice = taxa / (1 - Math.pow(1 + taxa, -parcelas));
17	        BigDecimal valorParcela = Dinheiro.arredondar(
18	            totalPedido.multiply(BigDecimal.valueOf(fatorPrice))
19	        );
20	
21	        BigDecimal totalFinal = valorParcela.multiply(BigDecimal.valueOf(parcelas));
22	        return Dinheiro.arredondar(totalFinal.subtract(totalPedido));
23	    }
